if (!function_exists('fi')) {
    /** Icon dùng lại từ sprite. */
    function fi(string $name, string $class = ''): string
    {
        return '<svg class="fi' . ($class !== '' ? ' ' . $class : '') . '" aria-hidden="true" focusable="false"><use href="#fi-' . htmlspecialchars($name, ENT_QUOTES) . '"/></svg>';
    }

    /** Sprite SVG ẩn chứa mọi icon (đặt một lần sau thẻ <body>). */
    function fi_sprite(): string
    {
        $out = '<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>';
        foreach (FINOVA_ICONS as $name => $paths) {
            $out .= '<symbol id="fi-' . $name . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' . $paths . '</symbol>';
        }
        return $out . '</defs></svg>';
    }
}
